/**
 * Generated by `ss app assets` (the `prebuild` script) — do not edit. The manifest with its element feature schemas
 * inlined and the string catalogs, bundled into the server build so nothing is read from disk at runtime.
 */
import manifest from '../../manifest.json' with { type: 'json' };
import feature0 from '../../schemas/adjustments.features.json' with { type: 'json' };
import feature1 from '../../schemas/earn_rules.features.json' with { type: 'json' };
import feature2 from '../../schemas/expiry.features.json' with { type: 'json' };
import feature3 from '../../schemas/redeem.features.json' with { type: 'json' };
import feature4 from '../../schemas/referrals.features.json' with { type: 'json' };
import feature5 from '../../schemas/reversal.features.json' with { type: 'json' };
import feature6 from '../../schemas/tiers.features.json' with { type: 'json' };
import feature7 from '../../schemas/wallet.features.json' with { type: 'json' };
import strings0 from '../../strings/en.json' with { type: 'json' };

/** @type {Record<string, unknown>} */
const features = {
	'schemas/adjustments.features.json': feature0,
	'schemas/earn_rules.features.json': feature1,
	'schemas/expiry.features.json': feature2,
	'schemas/redeem.features.json': feature3,
	'schemas/referrals.features.json': feature4,
	'schemas/reversal.features.json': feature5,
	'schemas/tiers.features.json': feature6,
	'schemas/wallet.features.json': feature7,
};

/** `createPlatform({ assets })` input: the manifest (features inline, as app-kit and the Portal take it) and strings. */
export const assets = {
	manifest: {
		...manifest,
		elements: /** @type {any[]} */ (manifest.elements).map((element) =>
			typeof element.features?.$ref === 'string' ? { ...element, features: features[element.features.$ref] } : element,
		),
	},
	strings: { en: strings0 },
};
